/* @lc app=leetcode id=919 lang=kotlin */ class CBTInserter(root: TreeNode?, val l: ArrayList<TreeNode> = arrayListOf(root!!).also { l -> generateSequence(0) { it + 1 }.takeWhile { it < l.size }.forEach { i -> listOfNotNull(l[i].left, l[i].right).forEach { l.add(it) } } }) { fun insert(`val`: Int): Int = TreeNode(`val`).let { n -> l.add(n).let { l[(l.size - 2) / 2] }.also { p -> if (p.left == null) p.left = n else p.right = n }.`val` } fun get_root(): TreeNode? = l[0] }